    def push(self, x):
        if self.standing:
            self.q.append(self.standing)
        self.standing = x

    # @return nothing
    def pop(self):
        self.standing = None
        if self.q and len(self.q)>0:
            newq = deque()
            for i in range(len(self.q)-1):
                newq.append(self.q.popleft())
            self.standing = self.q.popleft()
            self.q = newq

    # @return an integer
